pub(crate) fn detect_compound_extension(
    path: &str,
    extension: Option<&str>,
) -> Option<&'static str> {
    let basename = path.rsplit(['/', '\\']).next().unwrap_or(path);
    if basename.ends_with(".d.ts")
        || extension.is_some_and(|candidate| candidate.eq_ignore_ascii_case(".d.ts"))
    {
        return Some("typescript");
    }
    None
}

pub(crate) fn normalized_compound_extension(path: &str) -> Option<&'static str> {
    let basename = path.rsplit(['/', '\\']).next().unwrap_or(path);
    if basename.ends_with(".d.ts") {
        return Some(".d.ts");
    }
    None
}

pub(crate) fn detect_extension(extension: &str) -> Option<&'static str> {
    let extension = extension.to_ascii_lowercase();
    match extension.as_str() {
        ".py" | ".pyw" => Some("python"),
        ".js" | ".jsx" | ".mjs" | ".cjs" => Some("javascript"),
        ".ts" | ".d.ts" => Some("typescript"),
        ".tsx" => Some("tsx"),
        ".java" => Some("java"),
        ".c" => Some("c"),
        ".cpp" | ".cxx" | ".cc" => Some("cpp"),
        ".h" => Some("h"),
        ".hpp" | ".hxx" | ".hh" => Some("hpp"),
        ".cs" => Some("csharp"),
        ".go" => Some("go"),
        ".m" | ".mm" => Some("objective-c"),
        ".rb" => Some("ruby"),
        ".php" => Some("php"),
        ".swift" => Some("swift"),
        ".kt" | ".kts" => Some("kotlin"),
        ".rs" => Some("rust"),
        ".scala" => Some("scala"),
        ".sh" | ".bash" | ".zsh" => Some("shell"),
        ".ps1" | ".psm1" | ".psd1" => Some("powershell"),
        ".bat" | ".cmd" => Some("batch"),
        ".r" => Some("r"),
        ".pl" | ".pm" => Some("perl"),
        ".lua" => Some("lua"),
        ".dart" => Some("dart"),
        ".hs" => Some("haskell"),
        ".ml" | ".mli" => Some("ocaml"),
        ".fs" | ".fsx" => Some("fsharp"),
        ".clj" | ".cljs" => Some("clojure"),
        ".vim" => Some("vim"),
        ".zig" | ".zon" => Some("zig"),
        ".html" | ".htm" => Some("html"),
        ".css" | ".scss" | ".sass" | ".less" | ".stylus" | ".styl" => Some("css"),
        ".md" | ".mdx" => Some("markdown"),
        ".json" | ".jsonc" => Some("json"),
        ".xml" => Some("xml"),
        ".yml" | ".yaml" => Some("yaml"),
        ".toml" => Some("toml"),
        ".toon" => Some("toon"),
        ".txt" => Some("text"),
        ".ini" | ".cfg" | ".conf" | ".properties" | ".env" | ".gitignore" | ".dockerignore"
        | ".editorconfig" => Some("config"),
        ".vue" => Some("vue"),
        ".svelte" => Some("svelte"),
        ".astro" => Some("astro"),
        ".jsp" | ".jspx" | ".jspf" => Some("jsp"),
        ".tag" | ".tagx" => Some("jsp-tag"),
        ".gsp" => Some("gsp"),
        ".gradle" | ".groovy" => Some("groovy"),
        ".proto" => Some("protobuf"),
        ".hbs" | ".handlebars" => Some("handlebars"),
        ".ejs" => Some("ejs"),
        ".pug" => Some("pug"),
        ".ftl" => Some("freemarker"),
        ".mustache" => Some("mustache"),
        ".liquid" => Some("liquid"),
        ".erb" => Some("erb"),
        ".sql" | ".ddl" | ".dml" | ".mysql" | ".postgresql" | ".psql" | ".sqlite" | ".mssql"
        | ".oracle" | ".ora" | ".db2" | ".proc" | ".procedure" | ".func" | ".function"
        | ".view" | ".trigger" | ".index" | ".migration" | ".seed" | ".fixture" | ".schema"
        | ".cql" | ".cypher" | ".sparql" | ".liquibase" | ".flyway" => Some("sql"),
        ".gql" => Some("graphql"),
        _ => None,
    }
}

pub(crate) fn detect_exact_filename(file_name: &str) -> Option<&'static str> {
    match file_name {
        "Cargo.toml" => Some("cargo-manifest"),
        "Cargo.lock" => Some("cargo-lock"),
        "build.rs" => Some("rust-build-script"),
        "Dockerfile" => Some("dockerfile"),
        "Makefile" => Some("makefile"),
        _ => None,
    }
}
